    function v3RoughPlan(){
      const c=state.config,shots=[];let time=0;const add=(id,duration,text='',group=0,voiceover_id=0)=>{if(!id)return;const span=Math.max(.01,Number(duration)||5);shots.push({material_id:id,duration:span,source_in:0,source_out:span*c.speed,timeline_in:time,text,group,voiceover_id});time+=span;};
      if(c.mode==='storyboard')c.groups.forEach((g,i)=>add(g.material_ids[v3Variant%Math.max(1,g.material_ids.length)],g.duration,c.subtitle_mode==='group'?g.texts[0]||'':'',i+1,g.voiceover_ids[0]));
      else{let ids=[...c.material_ids];if(c.mode==='mix'&&ids.length){const offset=v3Variant%ids.length;ids=ids.slice(offset).concat(ids.slice(0,offset)).slice(0,Math.round((c.shot_range[0]+c.shot_range[1])/2));}const span=c.mode==='quick'?(c.duration_range[0]+c.duration_range[1])/2/Math.max(1,ids.length):(c.clip_range[0]+c.clip_range[1])/2;ids.forEach((id,i)=>add(id,span,c.subtitle_mode==='global'?c.subtitles[i%Math.max(1,c.subtitles.length)]||'':''));}
      return {shots,duration:time,title:c.titles[0]||'',subtitle:c.subtitle_mode==='global'?c.subtitles[0]||'':'',music_id:c.music_ids[0],voiceover_id:c.voiceover_ids[0],captions:c.captions||[]};
    }
